<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { eliminarVariableSunass, guardarVariableSunass, listarVariablesSunass } from '../services/variablesSunass'
import type { VariableSunass, VariableSunassPayload } from '../interfaces/variablesSunass.interface'
const records=ref<VariableSunass[]>([]),periodicities=ref<Record<string,string>>({}),query=ref(''),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),form=reactive<VariableSunassPayload>({nombre:'',descripcion:'',periodicidad:'',grupo_informacion:null})
const groups=computed(()=>new Set(records.value.map(x=>x.grupo_informacion)).size)
async function load(target=1){loading.value=true;error.value='';try{const r=await listarVariablesSunass(query.value,target);records.value=r.data;periodicities.value=r.periodicidades;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(item?:VariableSunass){editing.value=item?.id??null;Object.assign(form,item?{nombre:item.nombre,descripcion:item.descripcion,periodicidad:item.periodicidad,grupo_informacion:item.grupo_informacion}:{nombre:'',descripcion:'',periodicidad:'',grupo_informacion:null});modal.value=true}
async function save(){if(!form.nombre.trim()||!form.periodicidad||form.grupo_informacion==null){error.value='Complete el nombre, la periodicidad y el grupo de información.';return}saving.value=true;error.value='';try{await guardarVariableSunass({...form,nombre:form.nombre.trim(),descripcion:form.descripcion.trim()},editing.value??undefined);modal.value=false;success.value=`Variable SUNASS ${editing.value?'actualizada':'registrada'} correctamente.`;await load(editing.value?page.value:1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(item:VariableSunass){if(item.componentes_count){error.value='No se puede eliminar porque la variable está asociada a componentes.';return}if(!confirm(`¿Eliminar la variable ${item.nombre}?`))return;try{await eliminarVariableSunass(item.id);success.value='Variable SUNASS eliminada.';await load(page.value)}catch(e){error.value=message(e)}}
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Control de Calidad / Variables SUNASS</nav><header class="hero"><div class="mark">VS</div><div><small>DANA · CONTROL DE CALIDAD</small><h1>Variables SUNASS</h1><p>Configura variables regulatorias y su periodicidad de muestreo.</p></div><button @click="open()">+ Nueva variable</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="summary"><article><small>VARIABLES REGISTRADAS</small><b>{{total}}</b></article><article><small>GRUPOS DE INFORMACIÓN</small><b>{{groups}}</b></article><article><small>COMPONENTES ASOCIADOS</small><b>{{records.reduce((s,x)=>s+x.componentes_count,0)}}</b></article></section><form class="filters" @submit.prevent="load(1)"><div><small>FILTROS DE BÚSQUEDA</small><b>Buscar variables</b></div><input v-model.trim="query" placeholder="Nombre, descripción o periodicidad"><button>Buscar</button><button type="button" class="soft" @click="query='';load(1)">Limpiar</button></form><div v-if="loading" class="empty">Cargando variables SUNASS…</div><div v-else-if="!records.length" class="empty">No se encontraron variables.</div><section v-else class="cards"><article v-for="item in records" :key="item.id"><header><span>⌇</span><div><small>VARIABLE #{{item.id}}</small><h2>{{item.nombre}}</h2></div><em>G{{item.grupo_informacion}}</em></header><p>{{item.descripcion||'Sin descripción registrada.'}}</p><div class="period"><small>PERIODICIDAD</small><b>{{item.periodicidad_nombre||item.periodicidad}}</b></div><dl><div><dt>Componentes asociados</dt><dd>{{item.componentes_count}}</dd></div><div><dt>Fecha de creación</dt><dd>{{item.created_at}}</dd></div></dl><footer><button class="edit" @click="open(item)">Modificar</button><button class="delete" :disabled="!!item.componentes_count" @click="remove(item)">Eliminar</button></footer></article></section><footer v-if="lastPage>1" class="pager"><button :disabled="page===1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{lastPage}}</span><button :disabled="page===lastPage" @click="load(page+1)">Siguiente</button></footer><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div class="mark">VS</div><div><small>CONTROL DE CALIDAD</small><h2>{{editing?'Modificar':'Registrar'}} variable SUNASS</h2></div><button type="button" @click="modal=false">×</button></header><label>Nombre *<input v-model="form.nombre" maxlength="45" required></label><label>Descripción<textarea v-model="form.descripcion" maxlength="100" rows="3"></textarea><span>{{form.descripcion.length}} / 100</span></label><div class="row"><label>Periodicidad *<select v-model="form.periodicidad" required><option value="">Seleccione</option><option v-for="(name,key) in periodicities" :key="key" :value="key">{{name}}</option></select></label><label>Grupo de información *<input v-model.number="form.grupo_informacion" type="number" min="0" max="9" required></label></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
